(window.CLAYSIMS_TEXT = window.CLAYSIMS_TEXT || {})["uk"] = {"launch":"Запустити","method":"Метод","speed":"Швидкість мішені","distance":"Відстань","demo":"Показати метод","try":"Ваша черга: натисніть, коли стріляли б","shoot":"Постріл","hit":"Влучання! Мішень розбита.","behind":"Позаду — дріб пройшов позаду мішені","ahead":"Попереду — дріб пройшов попереду мішені","perceived":"Винос, який ви бачите в момент рішення","actual":"Фактичний винос у момент пострілу","lab_note":"Уповільнено, спрощена фізика для навчання. Дріб у польоті сповільнюється: у середньому близько 330 м/с на відстані 15 м, 300 м/с — на 25 м і 255 м/с — на 40 м (зі ствола він вилітає зі швидкістю близько 360–430 м/с). Від рішення до пострілу минає близько 0,15 с (усереднена оцінка). Кільце позначає ту частину осипу, яка досить густа, щоб розбити мішень: радіус близько 33 см на 15 м і 45 см на 40 м. Дульний зріз — приблизно за 1 м від ока. Відстані вздовж лінії польоту, винос і кільце показано в масштабі; мішень намальовано більшою, ніж насправді, щоб її було видно (приблизно в масштабі — там, де винос рахують у ширинах мішені). Фактичний винос залежить від швидкості, відстані й кута мішені, від набою та стрільця.","unit_m":"м","unit_ft":"фт","unit_ms":"м/с","pair_report":"{term}: друга мішень вилітає на звук першого пострілу","pair_sim":"{term}: обидві мішені вилітають разом","pair_rafale":"{term}: друга мішень з тієї ж машинки, щойно машинка перезарядиться","listen":"Прослухати","no_shot":"Пострілу не було.","at_muzzle":"біля дульного зрізу","compare":"Та сама мішень, чотири методи: фактичний винос однаковий, видимий — різний","how_maintained":"Стволи чекають попереду, і мішень наближається до них. Натисніть «Постріл», коли винос виглядає правильним: далі рушниця йде зі швидкістю мішені й тримає цей винос.","how_swing":"Стволи стартують позаду мішені й рухаються швидше за неї. Натисніть «Постріл», коли стволи проходять передній край мішені: за час затримки рушниця ще випереджає мішень, тому фактичний винос більший.","how_pullaway":"Стволи спершу йдуть разом із мішенню, потім прискорюються вперед. Натисніть «Постріл», поки рушниця ще прискорюється: видимий винос менший за фактичний.","how_ambush":"Стволи нерухомо чекають у точці попереду. Натисніть «Постріл» раніше, ніж мішень дійде до цієї точки: дробу потрібен час, тому постріл у мить, коли мішень уже в точці, іде позаду.","stop_gun":"Зупинити рушницю на спуску (помилка)","clay_widths":"ширин мішені","unit_cm":"см","unit_in":"дюйм.","anim_play":"Відтворити","anim_replay":"Ще раз","anim_slow":"Уповільнено","anim_marker":"з анімацією","anim_h_flight":"Подивіться, як летить мішень","anim_h_points":"Подивіться на три точки","anim_h_eyes":"Подивіться, куди дивляться очі","anim_h_stance":"Подивіться на стійку","anim_h_pair":"Подивіться, як подають дуплет","anim_h_lead":"Подивіться, як працює винос","anim_h_mount":"Подивіться на вкладку","anim_h_follow":"Подивіться на продовження руху","anim_h_call":"Подивіться на команду й виліт мішені","anim_h_gunpos":"Подивіться на положення рушниці","anim_h_misfire":"Подивіться, що робити після осічки","anim_w_flight":"Простежте всю траєкторію: звідки летить мішень, де її добре видно і куди вона йде.","anim_w_points":"Очі чекають у точці підхоплення, стволи — у точці утримання; мішень розбивається в точці пострілу.","anim_w_eyes":"М’який фокус навколо точки підхоплення, потім жорсткий фокус на передньому краї мішені.","anim_w_stance":"Носок передньої ноги дивиться на точку пострілу, а корпус повертається назад до точки утримання.","anim_w_pair":"Дивіться, коли вилітає друга мішень: після пострілу, разом із першою чи з тієї самої машинки.","anim_w_lead":"Дивіться на проміжок між стволами й мішенню в мить пострілу, а потім спробуйте самі.","anim_w_mount":"Спершу стволи рушають за мішенню, а вкладка завершується разом із пострілом.","anim_w_follow":"Рушниця рухається й після пострілу; зупиніть її на спуску — і дріб піде позаду.","anim_w_call":"Годинник показує, коли вилітає мішень після команди чи сигналу судді; запізніла мішень — No Bird.","anim_w_gunpos":"У Sporting™ приклад лишається нижче лінії на жилеті, доки не з’явиться мішень.","anim_w_misfire":"Після осічки стійте на місці: рушниця закрита й спрямована в бік поля, доки суддя її не огляне.","anim_unit_s":"с","anim_after_call":"після команди","anim_after_signal":"після сигналу","anim_t_signal":"Sporting™: сигнал судді","anim_t_late":"Запізніла мішень","anim_t_manual":"Compak® Sporting: вручну","anim_t_sonopull":"Compak® Sporting: {term}","anim_t_early":"Рушниця вже вгорі на команді","anim_s_in_time":"Мішень вилітає через {n} с після сигналу: вчасно (межа — {max} с).","anim_s_late":"Мішень вилітає через {n} с після сигналу, пізніше ніж за {max} с: суддя оголошує «No Bird», і мішень запускають знову.","anim_s_manual":"Ручний запуск: мішень вилітає через {n} с після команди (дозволено від 0 до {max} с).","anim_s_sonopull":"Сонопул: мікрофон чує команду, і мішень вилітає через {n} с — щоразу однаково.","anim_s_gun_low":"Вихідне положення: приклад торкається тіла нижче лінії на жилеті.","anim_s_gun_mount":"Мішень з’явилася: лише тепер рушницю вкладають у плече.","anim_s_early":"Команда з уже вкладеною рушницею: уперше — усне попередження й жовта картка.","anim_s_click":"Клац: рушниця не вистрілила.","anim_s_hold":"Стійте на місці: рушниця закрита й спрямована в бік поля; не відкривайте її й не торкайтеся запобіжника.","anim_s_ref":"Суддя оглядає рушницю.","anim_s_repeat":"Перша несправність у серії: мішень запускають знову.","anim_stop":"Зупинити","anim_s_mount_ready":"Готовність: рушниця внизу, очі чекають на мішень.","anim_s_move":"Рух: передня рука веде стволи вздовж лінії мішені.","anim_s_mount":"Вкладка: приклад піднімається до щоки й лягає в плече; голова нерухома.","anim_s_shoot":"Постріл: вкладка завершується разом із пострілом.","anim_scale":"У масштабі лише стрілець і стрілецьке місце; поле й політ мішені скорочено.","anim_h_pattern":"Подивіться, як чок змінює осип","anim_w_pattern":"Постріл по плиті з 36,6 м (40 ярдів). Оберіть чок: що він щільніший, то більше дробу в колі 76 см і то густіший осип на мішені в центрі.","anim_pattern_in":"У колі 76 см: ≈ {n} % дробу","anim_pattern_load":"Спрощено. 28 г дробу №7½ — це приблизно 370 дробин; відсотки — орієнтир для свинцевого дробу, з вашою рушницею й патроном вони можуть бути іншими. Мішень (110 мм) і коло — в масштабі.","anim_cheek":"щока на гребені","anim_l_foot":"передня нога","anim_l_body":"корпус"};
